import{_ as t,o as d,c as o,ak as a}from"./chunks/framework.BXerppJ0.js";const f=JSON.parse('{"title":"ast","description":"","frontmatter":{"sidebarDepth":0},"headers":[],"relativePath":"api/rpg-dice-roller/namespaces/ast/index.md","filePath":"api/rpg-dice-roller/namespaces/ast/index.md","lastUpdated":1794593361000}'),r={name:"api/rpg-dice-roller/namespaces/ast/index.md"};function i(c,e,n,s,l,h){return d(),o("div",null,[...e[0]||(e[0]=[a('<p><a href="./../../../">@dice-roller/rpg-dice-roller</a> / ast</p><h1 id="ast" tabindex="-1">ast <a class="header-anchor" href="#ast" aria-label="Permalink to &quot;ast&quot;">​</a></h1><p>Expression tree nodes and notation helpers for inspecting or constructing rolls.</p><h2 id="interfaces" tabindex="-1">Interfaces <a class="header-anchor" href="#interfaces" aria-label="Permalink to &quot;Interfaces&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Interface</th><th>Description</th></tr></thead><tbody><tr><td><a href="./interfaces/BinaryNode.html">BinaryNode</a></td><td>A binary maths operation, e.g. <code>2d6 + 3</code>.</td></tr><tr><td><a href="./interfaces/ComparePoint.html">ComparePoint</a></td><td>A comparison against a value, e.g. the <code>&gt;=8</code> in <code>8d10&gt;=8</code>.</td></tr><tr><td><a href="./interfaces/CriticalFailureNode.html">CriticalFailureNode</a></td><td><code>cf</code>.</td></tr><tr><td><a href="./interfaces/CriticalSuccessNode.html">CriticalSuccessNode</a></td><td><code>cs</code>.</td></tr><tr><td><a href="./interfaces/DescriptionNode.html">DescriptionNode</a></td><td>A roll description.</td></tr><tr><td><a href="./interfaces/DieNode.html">DieNode</a></td><td>The die of a pool: a reference to a die factory in the <code>DieRegistry</code>, and its arguments.</td></tr><tr><td><a href="./interfaces/DropNode.html">DropNode</a></td><td><code>d</code>, <code>dh</code>, <code>dl</code>.</td></tr><tr><td><a href="./interfaces/ExplodeNode.html">ExplodeNode</a></td><td><code>!</code>, <code>!!</code> (compound), <code>!p</code> (penetrate), <code>!!p</code>.</td></tr><tr><td><a href="./interfaces/FunctionNode.html">FunctionNode</a></td><td>A maths function call, e.g. <code>floor(2d6 / 2)</code>.</td></tr><tr><td><a href="./interfaces/GroupNode.html">GroupNode</a></td><td>A roll group, e.g. <code>{4d6+2d8, 3d20}k1</code>.</td></tr><tr><td><a href="./interfaces/KeepNode.html">KeepNode</a></td><td><code>k</code>, <code>kh</code>, <code>kl</code>.</td></tr><tr><td><a href="./interfaces/MaxNode.html">MaxNode</a></td><td><code>max5</code>.</td></tr><tr><td><a href="./interfaces/MinNode.html">MinNode</a></td><td><code>min2</code>.</td></tr><tr><td><a href="./interfaces/ModifiableOptions.html">ModifiableOptions</a></td><td>Options shared by pools and groups.</td></tr><tr><td><a href="./interfaces/NumberNode.html">NumberNode</a></td><td>A literal number, e.g. <code>4</code> or <code>-2.5</code>.</td></tr><tr><td><a href="./interfaces/ParenNode.html">ParenNode</a></td><td>A parenthesised expression, e.g. <code>(2+3)</code>. Kept so the notation round-trips.</td></tr><tr><td><a href="./interfaces/PoolNode.html">PoolNode</a></td><td>A pool of dice, e.g. <code>4d6kh3</code>.</td></tr><tr><td><a href="./interfaces/ReRollNode.html">ReRollNode</a></td><td><code>r</code>, <code>ro</code> and numeric re-roll limits.</td></tr><tr><td><a href="./interfaces/SortNode.html">SortNode</a></td><td><code>s</code>, <code>sa</code>, <code>sd</code>.</td></tr><tr><td><a href="./interfaces/TargetNode.html">TargetNode</a></td><td>Success / failure counting, e.g. <code>&gt;=8:2f&lt;=2</code>. The last matching rule in the block wins.</td></tr><tr><td><a href="./interfaces/TargetRule.html">TargetRule</a></td><td>A target comparison; amount is a whole number from 1 to 10 and defaults to 1.</td></tr><tr><td><a href="./interfaces/UnaryNode.html">UnaryNode</a></td><td>A unary minus, e.g. <code>-2</code>.</td></tr><tr><td><a href="./interfaces/UniqueNode.html">UniqueNode</a></td><td><code>u</code>, <code>uo</code> and numeric uniqueness limits.</td></tr></tbody></table><h2 id="type-aliases" tabindex="-1">Type Aliases <a class="header-anchor" href="#type-aliases" aria-label="Permalink to &quot;Type Aliases&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type Alias</th><th>Description</th></tr></thead><tbody><tr><td><a href="./type-aliases/BinaryOperator.html">BinaryOperator</a></td><td>A supported binary operator.</td></tr><tr><td><a href="./type-aliases/BuiltInDieName.html">BuiltInDieName</a></td><td>A built-in die factory name; registries can also contain custom names.</td></tr><tr><td><a href="./type-aliases/CompareOperator.html">CompareOperator</a></td><td>An operator accepted by a compare point.</td></tr><tr><td><a href="./type-aliases/DescriptionStyle.html">DescriptionStyle</a></td><td>- <code>inline</code>: <code>// text</code> or <code># text</code> - <code>block</code>: <code>/* text */</code> or <code>[text]</code></td></tr><tr><td><a href="./type-aliases/DieInput.html">DieInput</a></td><td>The die of a pool: a number of sides or an expression (a <code>standard</code> die, e.g. <code>6</code> or <code>paren(binary(&quot;+&quot;, 2, 3))</code>), or a <code>DieNode</code> from <code>die()</code>.</td></tr><tr><td><a href="./type-aliases/ExpressionInput.html">ExpressionInput</a></td><td>A number or an expression node.</td></tr><tr><td><a href="./type-aliases/ExpressionNodeType.html">ExpressionNodeType</a></td><td>The <code>type</code> of every expression node.</td></tr><tr><td><a href="./type-aliases/MathFunctionName.html">MathFunctionName</a></td><td>A supported maths function name.</td></tr><tr><td><a href="./type-aliases/ModifierName.html">ModifierName</a></td><td>The <code>name</code> of every modifier node.</td></tr><tr><td><a href="./type-aliases/ModifierNode.html">ModifierNode</a></td><td>A modifier selected by <code>name</code>; an omitted compare point uses the registered handler&#39;s default.</td></tr><tr><td><a href="./type-aliases/ModifierNodeOf.html">ModifierNodeOf</a></td><td>The modifier node with the given name.</td></tr><tr><td><a href="./type-aliases/PoolEnd.html">PoolEnd</a></td><td>Which end of the sorted rolls to keep / drop: <code>h</code>ighest or <code>l</code>owest.</td></tr><tr><td><a href="./type-aliases/SortDirection.html">SortDirection</a></td><td><code>a</code>scending or <code>d</code>escending.</td></tr></tbody></table><h2 id="variables" tabindex="-1">Variables <a class="header-anchor" href="#variables" aria-label="Permalink to &quot;Variables&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><a href="./variables/BINARY_OPERATORS.html">BINARY_OPERATORS</a></td><td>The binary maths operators. <code>**</code> is parsed as <code>^</code>.</td></tr><tr><td><a href="./variables/BUILT_IN_DIE_NAMES.html">BUILT_IN_DIE_NAMES</a></td><td>The names of the built-in die factories in the <code>DieRegistry</code>.</td></tr><tr><td><a href="./variables/COMPARE_OPERATORS.html">COMPARE_OPERATORS</a></td><td>Operators accepted by compare points; <code>!=</code> and <code>&lt;&gt;</code> both mean not equal.</td></tr><tr><td><a href="./variables/MATH_FUNCTION_NAMES.html">MATH_FUNCTION_NAMES</a></td><td>The supported maths functions.</td></tr></tbody></table><h2 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;Functions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Function</th><th>Description</th></tr></thead><tbody><tr><td><a href="./functions/binary.html">binary</a></td><td>A binary operation, e.g. <code>binary(&quot;+&quot;, pool(2, 6), 3)</code> for <code>2d6+3</code>.</td></tr><tr><td><a href="./functions/compare.html">compare</a></td><td>A compare point, e.g. <code>compare(&quot;&gt;=&quot;, 8)</code>.</td></tr><tr><td><a href="./functions/criticalFailure.html">criticalFailure</a></td><td>Flag critical failures using the supplied compare point or the handler default.</td></tr><tr><td><a href="./functions/criticalSuccess.html">criticalSuccess</a></td><td>Flag critical successes using the supplied compare point or the handler default.</td></tr><tr><td><a href="./functions/die.html">die</a></td><td>A reference to a die factory, e.g. <code>die(&quot;percentile&quot;)</code> for <code>d%</code>, or <code>die(&quot;range&quot;, -2, 3)</code>. Register custom names in the die registry used by the evaluator before rolling. Registration is not checked here; valid literal <code>range</code> and <code>face</code> dice use brace notation, while custom names and unsupported arguments have display-only notation.</td></tr><tr><td><a href="./functions/drop.html">drop</a></td><td>Drop <code>qty</code> highest (<code>h</code>) or lowest (<code>l</code>) items; quantity defaults to 1.</td></tr><tr><td><a href="./functions/explode.html">explode</a></td><td>Explode matching rolls. An optional positive safe-integer <code>limit</code> bounds additional rolls per initial die and is capped by the roll context&#39;s <code>maxIterations</code>.</td></tr><tr><td><a href="./functions/fn.html">fn</a></td><td>A maths function call, e.g. <code>fn(&quot;floor&quot;, binary(&quot;/&quot;, pool(2, 6), 2))</code>. Arity is checked at evaluation.</td></tr><tr><td><a href="./functions/group.html">group</a></td><td>A roll group, e.g. <code>group([pool(4, 6), pool(2, 8)])</code> for <code>{4d6, 2d8}</code>.</td></tr><tr><td><a href="./functions/keep.html">keep</a></td><td>Keep <code>qty</code> highest (<code>h</code>) or lowest (<code>l</code>) items; quantity defaults to 1.</td></tr><tr><td><a href="./functions/max.html">max</a></td><td>Cap die values at <code>value</code> with the built-in handler.</td></tr><tr><td><a href="./functions/min.html">min</a></td><td>Raise die values to at least <code>value</code> with the built-in handler.</td></tr><tr><td><a href="./functions/negate.html">negate</a></td><td>A unary minus.</td></tr><tr><td><a href="./functions/nodeToNotation.html">nodeToNotation</a></td><td>Converts an expression to canonical notation, e.g. a pool to <code>4d6kh3</code>.</td></tr><tr><td><a href="./functions/num.html">num</a></td><td>A literal number.</td></tr><tr><td><a href="./functions/paren.html">paren</a></td><td>A parenthesised expression.</td></tr><tr><td><a href="./functions/pool.html">pool</a></td><td>A pool of dice, e.g. <code>pool(4, 6)</code> for <code>4d6</code>, or <code>pool(2, die(&quot;fib&quot;))</code>.</td></tr><tr><td><a href="./functions/reRoll.html">reRoll</a></td><td>Re-roll matching dice. <code>once</code> is the <code>ro</code> alias; numeric <code>limit: 1</code> has the same budget but retains <code>r1</code> notation. Limits count additional rolls per die and cannot exceed the context cap.</td></tr><tr><td><a href="./functions/sort.html">sort</a></td><td>Sort ascending (<code>a</code>, the default) or descending (<code>d</code>).</td></tr><tr><td><a href="./functions/target.html">target</a></td><td>A target block starts with a success and can contain further success or failure rules. Amounts are 1–10 and default to 1; the last matching rule wins.</td></tr><tr><td><a href="./functions/unique.html">unique</a></td><td>Re-roll duplicate dice. <code>once</code> is the <code>uo</code> alias; numeric <code>limit: 1</code> has the same budget but retains <code>u1</code> notation. Limits count additional rolls per die and cannot exceed the context cap.</td></tr></tbody></table><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><h3 id="expressionnode" tabindex="-1">ExpressionNode <a class="header-anchor" href="#expressionnode" aria-label="Permalink to &quot;ExpressionNode&quot;">​</a></h3><p>Re-exports <a href="./../../../type-aliases/ExpressionNode.html">ExpressionNode</a></p>',14)])])}const u=t(r,[["render",i]]);export{f as __pageData,u as default};
